import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext"; // Correct import for useAuth

function Login({ role }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();
  const { login } = useAuth(); // Use the useAuth hook to access the login function

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      await login(email, password, role); // Pass the role to the login function
      if (role === "M") {
        navigate("/merchant-dashboard");
      } else if (role === "SA") {
        navigate("/admin-dashboard");
      }
    } catch {
      alert("Failed to log in!");
    }
  };

  return (
    <div className="login-page">
      <h1>Login</h1>
      <form onSubmit={handleLogin}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Login</button>
      </form>
    </div>
  );
}

export default Login;
